import numpy as np, itertools
from rdkit import Chem
m = Chem.MolFromMolFile('build/complex_raw.mol', removeHs=False)
X = np.array([list(m.GetConformer().GetAtomPosition(i)) for i in range(m.GetNumAtoms())])
E = [a.GetSymbol() for a in m.GetAtoms()]
nb = set()
for b in m.GetBonds():
    i,j = b.GetBeginAtomIdx(), b.GetEndAtomIdx()
    nb.add((min(i,j),max(i,j)))
# 1-2, 1-3, 1-4 exclusion
excl = set(nb)
for i in range(m.GetNumAtoms()):
    ni = [n.GetIdx() for n in m.GetAtomWithIdx(i).GetNeighbors()]
    for a in ni:
        for b2 in ni:
            if a<b2: excl.add((a,b2))
        for a2 in [n.GetIdx() for n in m.GetAtomWithIdx(a).GetNeighbors()]:
            pair=(min(i,a2),max(i,a2))
            excl.add(pair)
bad=[]
for i,j in itertools.combinations(range(len(X)),2):
    if (i,j) in excl or (i,j) in nb: continue
    d = np.linalg.norm(X[i]-X[j])
    lim = 1.6 if ('H' in (E[i],E[j])) else 2.2
    if d < lim: bad.append((i,j,E[i],E[j],round(d,2)))
for b in sorted(bad, key=lambda t:t[4])[:25]: print(b)
print('num bad', len(bad))
